const memoriesList = document.getElementById('memories-list');
memories.forEach((m, idx)=>{
  const row = document.createElement('div');
  row.className = 'memory-row' + (idx % 2 === 1 ? ' reverse' : '');
  const tilt = (idx % 2 === 0 ? -2 : 2) + (Math.random()*2-1);
  row.innerHTML = `
    <div class="memory-photo-wrap reveal">
      <div class="memory-polaroid" style="--tilt:${tilt}deg; --fdelay:${(idx*0.4)%3}s" data-index="${idx}">
        <span class="memory-number">${String(idx+1).padStart(2,'0')}</span>
        <div class="photo-inner"><img src="${m.img}" alt="${m.title}" loading="lazy" /></div>
        <div class="caption-tag">${m.title}</div>
      </div>
    </div>
    <div class="memory-text reveal">
      <h3 class="memory-title">${m.title}</h3>
      <div class="memory-story">${m.paras.map(p=>`<p>${p}</p>`).join('')}</div>
    </div>
  `;
  memoriesList.appendChild(row);
});

/* Lightbox */
const lightbox = document.getElementById('lightbox');
const lightboxImg = document.getElementById('lightbox-img');
const lightboxCaption = document.getElementById('lightbox-caption');
let lbIndex = 0;
function openLightbox(i){
  lbIndex = i;
  lightboxImg.src = memories[i].img;
  lightboxImg.alt = memories[i].title;
  lightboxCaption.textContent = memories[i].title;
  lightbox.classList.add('open');
}
function closeLightbox(){ lightbox.classList.remove('open'); }
function lbStep(dir){ lbIndex = (lbIndex + dir + memories.length) % memories.length; openLightbox(lbIndex); }

document.querySelectorAll('.memory-polaroid').forEach(el=>{
  el.addEventListener('click', ()=> openLightbox(parseInt(el.dataset.index,10)));
});
lightbox.querySelector('.lb-close').addEventListener('click', closeLightbox);
lightbox.querySelector('.lb-prev').addEventListener('click', ()=> lbStep(-1));
lightbox.querySelector('.lb-next').addEventListener('click', ()=> lbStep(1));
lightbox.addEventListener('click', (e)=>{ if(e.target === lightbox) closeLightbox(); });
window.addEventListener('keydown', (e)=>{
  if(!lightbox.classList.contains('open')) return;
  if(e.key==='Escape') closeLightbox();
  if(e.key==='ArrowLeft') lbStep(-1);
  if(e.key==='ArrowRight') lbStep(1);
});
/* Swipe support (mobile) */
let touchStartX = 0;
lightbox.addEventListener('touchstart', (e)=> touchStartX = e.changedTouches[0].clientX, {passive:true});
lightbox.addEventListener('touchend', (e)=>{
  const dx = e.changedTouches[0].clientX - touchStartX;
  if(Math.abs(dx) > 50) lbStep(dx > 0 ? -1 : 1);
}, {passive:true});

